def _patch_teleprint_frame():
    "Add a compositor after-frame hook; True if the patch was needed."
    if hasattr(Compositor, 'on_frame'): return False
    inner = Compositor._frame
    @functools.wraps(inner)
    def _frame(self):
        inner(self)
        if self.on_frame and not self.paused: self.on_frame()
    Compositor._frame, Compositor.on_frame = _frame, None
    return True

FRAME_PATCHED = _patch_teleprint_frame()

def _patch_teleprint_ink():
    "Stop a fold re-inking the transcript; True if the patch was needed."
    if 'self._ws = ws' not in inspect.getsource(Compositor._frame): return False
    inner = Compositor._frame
    @functools.wraps(inner)
    def _frame(self):
        was = self._ws
        inner(self)
        self._ws = max(was, self._ws)
    Compositor._frame = _frame
    return True

INK_PATCHED = _patch_teleprint_ink()

# %% ../nbs/05_cli.ipynb #extkeys01
KITTY_ON, KITTY_OFF = '\x1b[>1u', '\x1b[<u'
KEYS_ON, KEYS_OFF = KITTY_ON + '\x1b[>4;1m', KITTY_OFF + '\x1b[>4;0m'
EXT_NAMES = {13: 'enter', 9: 'tab', 27: 'escape', 127: 'backspace', 32: ' '}
#: kitty keypad keys; KP_BEGIN (57427) has no legacy name
EXT_NAMES.update(zip(range(57399, 57427), [*'0123456789./*-+', 'enter', '=', ',', 'left', 'right', 'up', 'down',
                                            'pageup', 'pagedown', 'home', 'end', 'insert', 'delete']))
EXT_CTRL = {105: 'tab', 106: 'enter', 109: 'enter'}
_KITTY_RE = re.compile(rb'\A\x1b\[(\d+)(?::\d*)*(?:;(\d*)(?::(\d+))?)?(?:;[\d:]*)?u')
_MOK_RE = re.compile(rb'\A\x1b\[27;(\d+);(\d+)~')

def ext_key(code, mods=1, event=1):
    "The `Key` for a kitty or modifyOtherKeys report, or None."
    m = (mods - 1) & ~0xc0
    if event == 3 or m > 7: return None
    if m == 4 and code in EXT_CTRL: return Key(EXT_CTRL[code])
    if m == 1 and code in (32, 127): m = 0
    name = EXT_NAMES.get(code) or (chr(code) if 32 < code < 0x110000 and not 0xd800 <= code < 0xf900 else None)
    if name is None: return None
    if len(name) == 1 and not m: return Key(name, name)
    return Key(_mod('space' if name == ' ' else name, m + 1))

def _patch_teleprint_keys():
    "Decode kitty and modifyOtherKeys reports; True if the patch was needed."
    if Parser().feed(b'\x1b[13;2u'): return False
    inner = Parser._csi
    @functools.wraps(inner)
    def _csi(self, buf):
        if m := _KITTY_RE.match(buf): return ext_key(int(m[1]), int(m[2] or 1), int(m[3] or 1)), m.end()
        if m := _MOK_RE.match(buf): return ext_key(int(m[2]), int(m[1])), m.end()
        return inner(self, buf)
    Parser._csi = _csi
    return True

KEYS_PATCHED = _patch_teleprint_keys()

def ext_keys_ok(tty):
    "Whether `tty` is a real terminal at both ends."
    return hasattr(tty, 'fd') and os.isatty(tty.fd) and sys.stdout.isatty()

def _patch_teleprint_modes():
    "Hold extended keys while the compositor holds a real terminal; True if patched."
    if hasattr(Compositor, 'ext_keys'): return False
    C, T = Compositor, TranscriptView
    start, stop, release, reanchor, fatal, signals, dispatch = (C.start, C.stop, C.release, C.reanchor,
                                                                C._fatal, C._register_signals, C._dispatch)
    enter, leave = T.enter, T.leave
    def keys(self, on):
        if self.ext_keys: self.tty.write(KEYS_ON if on else KEYS_OFF)
    async def _start(self):
        self.ext_keys = ext_keys_ok(self.tty)
        await start(self)
        self.keys(True)
        return self
    def _register_signals(self):
        signals(self)
        if self.ext_keys and signal.SIGINT in self._signals:
            asyncio.get_running_loop().add_signal_handler(signal.SIGTSTP, lambda: self.spawn(self.suspend()))
            self._signals.append(signal.SIGTSTP)
    async def suspend(self):
        "Stop as ctrl+z would, giving the terminal back first and taking it again on `fg`."
        loop, fd, alt = asyncio.get_running_loop(), self.tty.fd, self.paused
        mode = termios.tcgetattr(fd)
        if alt: self.tty.write(KITTY_OFF + '\x1b[?1049l')
        self.release()
        self.tty.restore()
        held = loop.remove_signal_handler(signal.SIGTSTP)
        os.kill(os.getpid(), signal.SIGTSTP)
        if held: loop.add_signal_handler(signal.SIGTSTP, lambda: self.spawn(self.suspend()))
        termios.tcsetattr(fd, termios.TCSANOW, mode)
        await self.reanchor()
        if alt: self.tty.write('\x1b[?1049h' + KITTY_ON)
        self._on_winch()
    def _dispatch(self, ev):
        if self.ext_keys and isinstance(ev, Key) and ev.name == 'ctrl+z': return self.spawn(self.suspend())
        return dispatch(self, ev)
    def _stop(self): self.keys(False); stop(self)
    def _release(self): release(self); self.keys(False)
    async def _reanchor(self): await reanchor(self); self.keys(True)
    def _fatal(self, sig): self.keys(False); fatal(self, sig)
    def _enter(self):
        enter(self)
        if self.comp.ext_keys: self.comp.tty.write(KITTY_ON)
    def _leave(self):
        if self.comp.ext_keys: self.comp.tty.write(KITTY_OFF)
        leave(self)
    C.ext_keys, C.keys, C.suspend = False, keys, suspend
    C.start, C.stop, C.release, C.reanchor, C._fatal = _start, _stop, _release, _reanchor, _fatal
    C._register_signals, C._dispatch, T.enter, T.leave = _register_signals, _dispatch, _enter, _leave
    return True

MODES_PATCHED = _patch_teleprint_modes()

