def file_refs(text):
    "Relative paths named as `@path` in a prompt, with sentence punctuation removed."
    out = []
    for m in ATTACH_REF.finditer(str(text or '')):
        tok = m.group(1)
        while tok and tok[-1] in TRAILING: tok = tok[:-1]
        if tok: out.append(tok)
    return out

