def _now_file(agent): return None if (d := agent.runs_dir) is None else d/'now.json'

class Ui:
    "The terminal surface: a transcript of blocks, a status bar, and one line to type in."

    def __init__(self, comp, agent, loop=None):
        self.comp, self.agent, self.loop = comp, agent, loop
        comp.console.push_theme(MARKDOWN_THEME)
        self.buf = Buffer()
        self.ask = None
        self._asked_at = 0.0
        self.turn = None
        self.starting = self.closed = False
        self._queued = None
        self._queued_prompt = None
        self._prompt = None
        self._flash = None
        self._queued_echo = []
        self._hold = False
        self.pane, self._pane_at, self._alive_at, self._reopen_at = None, None, 0.0, 0.0
        self._opened_at, self._quick = None, 0
        self._now_at, self._now_busy, self._now_dirty = 0.0, False, False
        self._echoed = []
        self.acts = {}
        self.by_id = {}
        self.kids = {}
        self.hint = ''
        self.mode = 'agent'
        self.kernel = None
        self.attached = ''
        self.agent_bridge = None
        self.proxy_url = ''
        from ramabana.runtime import TokenLogger
        TokenLogger.sink = self._usage_line
        self._join_ask = ''
        self._suggesting = False
        self.desc = []
        self.attachments = []
        self.pics = {}
        self.drawn = 0
        self.frame = 0
        self._reply = ''
        self._seg = ''
        self._seg_blk = None
        self._painted_at = 0.0
        self._acted_at = 0.0
        self._held = set()
        self._turn_at = 0.0
        self._turn_from = 0
        self._rendered = ''
        self._plan_blk = None
        self._touched = 0.0
        self.history, self.history_at, self.draft = [], 0, ''
        self.menu = None
        self.menu_prompt = ''
        self.complete = None
        self.show_plan = bool(agent.plan)
        self.mouse = False
        self.bell, self._key_at = True, time.monotonic()
        self._stop_at, self._stop_count, self._stop_run = 0., 0, ''
        self.transcript = TranscriptView(comp, self.tail)
        self._compact_until = 0.0
        agent.activity.on_change = self.on_act
        agent.on_media = self.on_media
        agent.on_plan = self.on_plan
        self._compact_hook = getattr(agent.compactor, 'on_compact', None)
        agent.compactor.on_compact = self._on_compact
        if agent.approvals is not None: agent.approvals.listen(self.on_ask, self.on_answer)
        comp.on_frame, comp.toggle = self.place_pics, self.toggle

    def _post(self, fn, *a):
        "Run `fn` on the loop thread, or now without a loop."
        if self.loop is None: return fn(*a)
        self.loop.call_soon_threadsafe(fn, *a)

    def _as_owner(self, work, timeout=10):
        "Run `work` on the loop that owns the agent and return what it returned."
        if self.loop is None: return work()
        held = concurrent.futures.Future()
        def run():
            try: held.set_result(work())
            except Exception as e: held.set_exception(e)
        self.loop.call_soon_threadsafe(run)
        return held.result(timeout)

    def _usage_line(self, text):
        "The `TokenLogger` sink, posted from the turn thread."
        self._post(lambda: self.note(text))

    def _on_compact(self, text):
        if self._compact_hook:
            try: self._compact_hook(text)
            except Exception: pass
        self._post(self._show_compact)

    def _show_compact(self):
        self._compact_until = time.monotonic() + 1.5
        self.paint()
        if self.loop is not None: self.loop.call_later(1.5, self.paint)


    WORDMARK = 'ℝ𝔸𝕄𝔸𝔹𝔸ℕ𝔸'

    SPINNER = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'

    TRACK = '·'
    BOW_FRAMES = ('»═▸·····', '·»═▸····', '···»═▸··', '·····»═▸')
    COMPACT_BOW = '··▸··◂··'

    BOW_CYCLE = (0, 0, 0, 0, 0, 1, 1, 1, 2, 2, 3, 3)

    def bow_text(self, busy=False, style=None):
        "The art as spans: the track quiet, the arrow in `style`."
        out, frame = Text(), self.bow(busy)
        for ch in frame: out.append(ch, style=GRUVBOX['gray'] if ch == self.TRACK else style)
        return out

    def bow(self, busy=False):
        "The bow frame for this tick: moving while busy, at rest otherwise."
        if self._compact_until > time.monotonic(): return self.COMPACT_BOW
        if not busy: return self.BOW_FRAMES[0]
        return self.BOW_FRAMES[self.BOW_CYCLE[self.frame % len(self.BOW_CYCLE)]]

    def status(self):
        "The status bar: what is loaded, whether it is working, and what it has cost."
        if self.starting: s, busy, state, color = None, True, 'starting model…', GRUVBOX['yellow']
        else:
            s = self.agent.status()
            busy = self.turn is not None or s['busy']
            state = 'working' if busy else ('ready' if s['ready'] else 'idle')
            color = GRUVBOX['yellow'] if busy else GRUVBOX['green'] if s['ready'] else GRUVBOX['gray']
        mark = self.SPINNER[self.frame % len(self.SPINNER)] if busy else '●'
        out = self.bow_text(busy, color); out.append(' ')
        out.append(self.WORDMARK, style=f"bold {GRUVBOX['fg0']}")
        out.append(f" {VERSION}", style=GRUVBOX['gray'])
        out.append(f"  {s['model'] if s else self.agent.model.name}  ", style=GRUVBOX['gray'])
        out.append(f'{mark} {state.lower()}', style=color)
        if s is None: return out
        bits = [f"{s['ntools']} tools", f"{s['nskills']} skills", f"{round(s['pct_full'] * 100)}% ctx"]
        if s.get('plan_line'): bits.append(s['plan_line'])
        if s['compactions']: bits.append(f"{s['compactions']} compacted")
        if self.agent.use.total: bits.append(s['usage'])
        if s['problems']: bits.append(f"{len(s['problems'])} problems")
        out.append('  ' + ' · '.join(bits), style=GRUVBOX['gray'])
        if self.kernel is not None:
            out.append(f'  · {self.mode}', style=GRUVBOX['aqua'] if self.mode == 'python' else GRUVBOX['blue'])
        return out

    def turn_blocks(self):
        "The blocks of the turn on screen: everything printed since its prompt went up."
        return [b for b in self.comp.blocks.values() if b.id >= self._turn_from and not b.committed]

    def drillable(self):
        "The turn's foldable entries, newest first: what alt+1..9 reaches."
        return [b for b in reversed(self.turn_blocks())
                if b.tag in ('step', 'tool') and b.height > 1][:9]

    def drill(self, n):
        "Toggle the `n`th newest foldable entry; False if there is none."
        self.flush_stream()
        blocks = self.drillable()
        if not 1 <= n <= len(blocks): return False
        self.toggle(blocks[n - 1])
        self.touch(now=True)
        return True

    def toggle(self, blk):
        "Fold or open `blk` for good; a result shown in part opens whole first."
        capped = self._capped(blk)
        self._held.add(blk.id)
        if capped: self.comp.refresh_block(blk)
        else: Compositor.toggle(self.comp, blk)

    def working(self):
        "The working footer while a turn runs: the last few calls and a totals line."
        if self.starting or (self.turn is None and not self.agent.busy): return []
        acts = self.agent.activity.since()
        nums = {b.id: i + 1 for i, b in enumerate(self.drillable())}
        rows = []
        for a in acts[-ACT_TAIL:]:
            style = GRUVBOX['yellow'] if not a.done else GRUVBOX['gray'] if a.ok else GRUVBOX['red']
            parent = self.acts.get(a.parent_action_id) if a.parent_action_id else None
            blk = parent if parent is not None else self.acts.get(a.id)
            n = nums.get(blk.id) if blk is not None else None
            t = Text(f'{n} ' if n else '  ', style=GRUVBOX['blue'] if n else GRUVBOX['gray'])
            t.append(('  ' if parent is not None else '') + a.line(), style=style)
            rows.append(t)
        mine = [a for a in acts if not a.parent_action_id or a.parent_action_id not in self.acts]
        bits = [f'step {len(mine)}' if mine else 'thinking']
        if self._turn_at: bits.append(f'{time.monotonic() - self._turn_at:.0f}s')
        if (sub := len(acts) - len(mine)): bits.append(f'{sub} delegated')
        if (n := sum(1 for a in acts if not a.done)) > 1: bits.append(f'{n} in flight')
        rows.append(Text('  ' + ' · '.join(bits), style=GRUVBOX['gray']))
        return rows

    async def animate(self):
        "Repaint the live tail while a turn runs."
        while True:
            await asyncio.sleep(0.1)
            if self.ask is not None: self.nudge()
            if self.turn is not None:
                self.frame += 1
                self.flush_stream()
                self.paint()
            if self.turn is not None or self._now_busy or self._now_dirty: self.write_now()
            if self.pane is not None and _now_file(self.agent) != self._pane_at: self.open_pane()
            self._revive()

    def write_now(self, force=False):
        "Write `now.json` for the pane, at most every `PANE_EVERY` seconds unless `force`."
        if self.starting or (p := _now_file(self.agent)) is None: return
        t = time.monotonic()
        if not force and t - self._now_at < PANE_EVERY:
            self._now_dirty = True
            return
        self._now_at, self._now_dirty = t, False
        try: write_snapshot(self.agent, p)
        except Exception: return   # a snapshot that fails must never stop the animate loop
        self._now_busy = self.agent.busy

    ASKING, PY_LABEL, CONT = 'approve? [y/n/a · n: reason] ', 'python › ', '...      '

    def prompt(self):
        "The input line: an approval question when one is pending, otherwise the prompt."
        if self.ask is not None:
            return Text(self.ASKING, style=f"bold {GRUVBOX['yellow']}") + Text(self.buf.text, style=GRUVBOX['fg0'])
        if self.mode == 'python':
            from ramabana.pyrepl import hl
            body = Text('\n' + self.CONT, style=GRUVBOX['fg0']).join(hl(self.buf.text).split('\n', allow_blank=True))
            return Text(self.PY_LABEL, style=f"bold {GRUVBOX['aqua']}") + body
        return Text('▌ ', style=f"bold {GRUVBOX['blue']}") + Text(self.buf.text, style=GRUVBOX['fg0'])

    def _prefixed(self, text):
        "`text` with what precedes it on screen, as `tail` measures it."
        if self.ask is not None: return self.ASKING + text
        if self.mode == 'python': return self.PY_LABEL + text.replace('\n', '\n' + self.CONT)
        return '▌ ' + text

    def _suggest_soon(self):
        "Start a kernel completion for the token being typed."
        if self.mode != 'python' or self.kernel is None or self._suggesting: return
        if self.turn is not None or self.ask is not None: return
        tok = re.split(r'[^\w.]', self.buf.text[:self.buf.cursor])[-1]
        if len(tok) < 2 or tok.endswith('..'): return
        self._suggesting = True
        self.comp.spawn(self._suggest(), name='suggest')

    def overlay(self):
        "Transient rows above the tail: options, slash completion, or the plan checklist."
        if self.menu is not None: return self.menu.render()
        if self.complete is not None:
            rows = [self.complete.renderable()]
            if self.desc: rows.append(Text('  '.join(self.desc), style=GRUVBOX['gray']))
            return rows
        if self.show_plan and self.agent.plan:
            return [Tooltip(self.agent.plan.md(), max_lines=12).renderable()]
        return []

    def paint(self):
        "Repaint the live tail, and the browsing view when it is up."
        rows, cursor = self.tail()
        self.comp.set_tail(*rows, cursor=cursor, over=self.overlay())
        if self.transcript.active: self.transcript.draw()

    def touch(self, now=False):
        "Let a following transcript view track new blocks, like `less +F`."
        if now: self.flush_stream()
        if not self.transcript.active: return
        t = time.monotonic()
        if not now and t - self._touched < NOTIFY_EVERY: return
        self._touched = t
        self.transcript.notify()


    def say(self, body, kind='reply', fold=FOLD, source=None, pad=False):
        "Print one block; strings stay literal, Rich renderables keep their style."
        if source is None:
            if isinstance(body, str): source = body
            elif isinstance(body, Text): source = body.plain
        body = Text(body) if isinstance(body, str) else body
        blk = self.comp.print_block(body, gutter=GUTTERS.get(kind, GUTTERS['reply']),
                                    tag=kind, collapse_at=fold, source=source, pad=pad)
        if kind != 'reply' and (reply := self._seg_blk) is not None:
            self.comp._epoch.remove(reply.id)
            self.comp._epoch.append(reply.id)
            self.comp.blocks.pop(reply.id)
            self.comp.blocks[reply.id] = reply
            self.comp._frame()
        self.touch(now=True)
        return blk

    def note(self, text, kind='note'):
        "Print one unfolded `kind` block; returns None."
        self.say(Text(text), kind, fold=None)
        return None

    def fold_work(self):
        "Open or shut every step and call of the turn; True when shut."
        self.flush_stream()
        work = [b for b in self.turn_blocks() if b.tag in ('step', 'tool') and b.height > 1]
        if not work: return False
        shut = not all(b.collapsed or self._capped(b) for b in work)
        for b in work:
            b.collapsed = shut
            self._held.add(b.id)
            self.comp._dirty(b)
        self.comp._frame()
        self.touch(now=True)
        return shut

    def on_act(self, act):
        "Post a tool call's change from the model's thread: running, then done."
        self._post(self._act, act)

    def _act_style(self, act):
        "Blue while it runs, green when it worked, red when it did not."
        return GRUVBOX['blue'] if not act.done else GRUVBOX['green'] if act.ok else GRUVBOX['red']

    def _folded(self, act, blk):
        "Whether a call folds to its summary row."
        if blk.id in self._held: return blk.collapsed
        if blk.height <= FOLD_TOOL: return False
        if not act.done: return FOLD_RUNNING and act.id not in self.kids
        return act.ok and (act.id in self.kids or not opens(act))

    def _capped(self, blk):
        "Whether `blk` is open on a result it shows only in part."
        return not blk.collapsed and any(getattr(p, 'capped', False) for p in blk.body)

    def _detail(self, act, blk):
        "A call's result as `diff_rich` draws it; a finished call that `opens` shows it capped."
        t = diff_rich(act.detail)
        return OpenDiff(self, blk, t) if act.done and act.ok and opens(act) else t

    def _echo(self, body, kind='user', **kw):
        "Print what was typed, retractable until its turn starts."
        blk = self.say(body, kind, **kw)
        self._echoed.append((blk, body, kind, kw))
        return blk

    def _retract(self):
        "Remove the typed entry before its turn starts."
        held, self._echoed = self._echoed, []
        for blk, *_ in held: self.comp.remove_block(blk)
        return held

    def _replay(self, held):
        "Print retracted entries again where their turn starts."
        for _, body, kind, kw in held: self._echo(body, kind, **kw)

    def _turn(self, prompt):
        "A turn over `prompt`, remembered so a queued line can join it."
        self._prompt = prompt
        return run_turn(self, prompt)

    def start_turn(self, coro, prompt=None):
        "Spawn a turn, or queue it behind the running one; True if it started."
        prompt, self._prompt = (self._prompt if prompt is None else prompt), None
        if self._turn_over(): self.turn = None
        if self.turn is not None:
            if self._queued is not None:
                if prompt is None or self._queued_prompt is None:
                    coro.close()
                    self._retract()
                    self.note('something is already waiting · ctrl+c clears it and stops this turn')
                    return False
                coro.close(); self._queued.close()
                self._queued_prompt += '\n\n' + prompt
                self._queued = run_turn(self, self._queued_prompt)
                self._queued_echo += self._retract()
                self.flash('absorbed into the queued message')
                return False
            self._queued, self._queued_prompt, self._queued_echo = coro, prompt, self._retract()
            self.note('queued · it runs when this turn ends · ctrl+c stops and clears it')
            return False
        self.turn = self.comp.spawn(coro, name='turn')
        self._echoed = []
        self.turn.add_done_callback(lambda _t: self._next_queued())
        return True

    def steer(self, line):
        "Send `line` into the running turn; False if none listens or it has files."
        if self.turn is None or self.attachments or file_refs(line) or not self.agent.steer(line): return False
        self._retract()
        self._echo(Text('↪ ' + line), 'user', pad=True)
        self._echoed = []
        self.flash('sent · read after the current call')
        return True

    def _turn_over(self):
        "Whether the turn in flight is done; objects without `done()` never are."
        return self.turn is not None and getattr(self.turn, 'done', bool)()

    def _next_queued(self):
        "After the turn ends, run unread steering joined with any queued line."
        if self._turn_over(): self.turn = None
        # the running turn drains this when it ends
        if self.turn is not None: return
        if (left := '\n\n'.join(self.agent.leftovers())):
            if self._queued is not None and self._queued_prompt is None:
                self.start_turn(run_turn(self, left), prompt=left)
                return self.paint()
            if self._queued is not None: self._queued.close(); left += '\n\n' + self._queued_prompt
            self._queued, self._queued_prompt = run_turn(self, left), left
        if self._queued is None: return
        held, hp, echo = self._queued, self._queued_prompt, self._queued_echo
        self._queued, self._queued_prompt, self._queued_echo = None, None, []
        self._replay(echo)
        try:
            if self.start_turn(held, prompt=hp): self.flash('queued message sent')
        except Exception as e:
            self._queued, self._queued_prompt, self._queued_echo = held, hp, self._retract()
            self.note(f'the waiting message did not start: {agent_err(e)}', 'error')
        self.paint()

    def drop_queued(self):
        "Forget a waiting line and any unread steering."
        unread = self.agent.leftovers()
        if self._queued is None and not unread: return False
        if self._queued is not None: self._queued.close()
        self._queued, self._queued_prompt, self._queued_echo = None, None, []
        self.note('the waiting message was cleared')
        return True

    def _act(self, act):
        if act.parent_action_id and act.parent_action_id in self.acts: return self._nest(act)
        self.by_id[act.id] = act
        blk = self.acts.get(act.id)
        if blk is None:
            self._close_seg()
            line = Text(act.line(), style=self._act_style(act))
            self.acts[act.id] = self.say(line, 'tool', source=act.line())
            return self.paint()
        if act.id in self.kids: self._paint_group(act.id)
        else:
            line = Text(act.line(), style=self._act_style(act))
            src = act.line() if not act.detail else f'{act.line()}\n{act.detail}'
            body = [line] if not act.detail else [line, self._detail(act, blk)]
            self.comp.set_body(blk, *body, source=src)
            blk.collapsed = self._folded(act, blk)
            self.comp.refresh_block(blk)
            if act.done: self.by_id.pop(act.id, None)
        self.touch()
        now = time.monotonic()
        if act.done or now - self._acted_at >= ACT_EVERY:
            self._acted_at = now
            self.paint()

    def _nest(self, act):
        "Fold a sub-agent's call into the delegate that asked for it."
        kids = self.kids.setdefault(act.parent_action_id, [])
        if not any(k.id == act.id for k in kids): kids.append(act)
        self._paint_group(act.parent_action_id)
        self.touch()
        return self.paint()

    def _paint_group(self, pid):
        "Redraw a delegate and its sub-agent's calls as one foldable block."
        if pid not in self.by_id: return
        act, blk, kids = self.by_id[pid], self.acts[pid], self.kids.get(pid, [])
        head = Text(act.line(), style=self._act_style(act))
        if kids: head.append(f'  · {len(kids)} call{"" if len(kids) == 1 else "s"}', style=GRUVBOX['gray'])
        shown, body = kids[-MAX_GROUP_ROWS:], [head]
        if len(kids) > len(shown):
            body.append(Text(f'   … {len(kids) - len(shown)} earlier', style=GRUVBOX['gray']))
        body += [Text('   ' + k.line(), style=self._act_style(k)) for k in shown]
        if act.detail: body.append(diff_rich(act.detail))
        src = '\n'.join([act.line()] + ['   ' + k.line() for k in kids] + ([act.detail] if act.detail else []))
        self.comp.set_body(blk, *body, source=src)
        blk.collapsed = self._folded(act, blk)
        self.comp.refresh_block(blk)


    def on_ask(self, ask):
        "Show a waiting write and take over the input line."
        self._post(self._ask, ask)

    def _ask(self, ask):
        self.ask = ask
        self.buf.clear()
        self.reask(ask.preview)

    def on_answer(self, ask):
        self._post(self._answered, ask)

    def _answered(self, ask):
        if self.ask is not None and self.ask.id == ask.id: self.ask = None
        self.say(Text(answer_md(ask).replace('**', '')), 'note')
        self.paint()

    def answer(self, ok, session=False, note=None):
        "Answer the pending request with `note`, else the typed line."
        if self.ask is None: return None
        note, self.buf.text = ifnone(note, self.buf.text.strip()), ''
        return self.agent.approvals.answer(self.ask.id, ok, note, session=session)


    def attach(self, path):
        "Attach one media file to the next prompt, or say why not."
        p = media_path(path)
        if p is None: return 'nothing to attach'
        if p.is_dir(): return f'cannot attach {p.name}: it is a folder'
        if not p.exists(): return f'cannot attach {p.name}: no such file'
        if p.suffix.lower() not in MEDIA: return f'cannot attach {p.name}: {p.suffix or "no suffix"} is not media'
        if p.stat().st_size > MAX_MEDIA:
            return f'cannot attach {p.name}: {_human(p.stat().st_size)} is over the {_human(MAX_MEDIA)} limit'
        if len(self.attachments) >= MAX_ATTACH: return f'cannot attach {p.name}: {MAX_ATTACH} is the limit'
        a = Attachment(p)
        if any(x.path == a.path for x in self.attachments): return f'{a.name} is already attached'
        self.attachments.append(a)
        return f'attached {a.kind} {a.label()}'

    def detach(self, which=''):
        "Drop one attachment by 1-based index or name, or all of them."
        if not self.attachments: return 'nothing is attached'
        if not which:
            n, self.attachments = len(self.attachments), []
            return f'dropped {n} attachment' + ('s' if n > 1 else '')
        if which.isdigit() and 1 <= int(which) <= len(self.attachments):
            return f'dropped {self.attachments.pop(int(which) - 1).name}'
        hit = next((a for a in self.attachments if a.name == which), None)
        if hit is None: return f'not attached: {which}'
        self.attachments.remove(hit)
        return f'dropped {hit.name}'

    def attach_clipboard(self):
        "Attach the clipboard picture via a temporary file."
        png = clipboard_png()
        if png is None:
            if not any(shutil.which(c[0]) for c in CLIP_IMAGE):
                return ('no clipboard image helper found: install pngpaste (macOS), '
                        'wl-clipboard or xclip (linux)')
            return 'no image on the clipboard'
        fd, name = tempfile.mkstemp(prefix='ramabana-paste-', suffix='.png')
        with os.fdopen(fd, 'wb') as f: f.write(png)
        return self.attach(name)

    def attach_row(self):
        "The attachment chips above the prompt, or None."
        if not self.attachments: return None
        row = Text(' ')
        for i, a in enumerate(self.attachments):
            if i: row.append('  ')
            row.append(f"{'◧' if a.kind == 'image' else '♪'}{i + 1} {a.label()}", style=GRUVBOX['aqua'])
        row.append('   /detach to drop', style=GRUVBOX['gray'])
        return row

    def flash(self, text, secs=FLASH_FOR):
        "Show a self-clearing line above the prompt."
        self._flash = (text, time.monotonic() + secs)

    def flash_row(self):
        "The self-clearing line, while it is still up."
        if self._flash is None: return None
        if time.monotonic() >= self._flash[1]:
            self._flash = None
            return None
        return Text(' \u2713 ' + self._flash[0], style=GRUVBOX['green'])

    def queued_row(self):
        "The row showing the message waiting for this turn to end."
        if self._queued is None: return None
        what = ' '.join((self._queued_prompt or '').split()) or 'a command'
        row = Text(' \u23f3 queued  ', style=GRUVBOX['yellow'])
        row.append(what[:79] + '\u2026' if len(what) > 80 else what, style=GRUVBOX['fg0'])
        row.append('   ctrl+c clears it', style=GRUVBOX['gray'])
        return row

    def copy_last(self, tag='reply'):
        "Copy the newest `tag` block to the system clipboard with OSC 52."
        tag = (tag or 'reply').strip() or 'reply'
        if tag == 'turn':
            if not self._reply: return 'no turn to copy'
            text = self._reply
        else:
            blk = next((b for b in reversed(self.turn_blocks()) if b.tag == tag), None)
            if blk is None: return f'no {tag} block in this turn to copy'
            text = self.transcript.block_text(blk)
        self.comp.tty.write('\x1b]52;c;' + b64encode(text.encode()).decode() + '\x07')
        return f'copied {len(text)} chars of the last {tag}'


    def on_plan(self, plan):
        "Repaint when the checklist changes."
        self.show_plan = bool(plan)
        self._post(self._paint_plan, plan)

    def _paint_plan(self, plan):
        "Keep one plan block for the turn and rewrite it."
        if not plan: return
        md = plan.md()
        if (blk := self._plan_blk) is None:
            self._plan_blk = self.say(plan_text(md), 'plan', fold=None, source=md)
            return
        self.comp.set_body(blk, plan_text(md), source=md)
        self.comp.refresh_block(blk)
        self.touch(now=True)
        self.paint()

    def _slash_matches(self):
        text = self.buf.text
        if not text.startswith('/') or ' ' in text: return None
        prefix = text[1:].lower()
        names = {*self.agent.commands(), *SURFACE_COMMANDS}
        hits = sorted(f'/{n}' for n in names if n.startswith(prefix))
        return hits or None

    def _refresh_complete(self):
        hits = self._slash_matches()
        if not hits:
            self.complete = None
            return
        self.complete = CompletionMenu(self.buf, hits, start=0, show=8)

    def guide(self):
        "The `/guide` text; subclasses extend it."
        return GUIDE

    def submit(self):
        "Handle the typed line. Returns a coroutine for a turn, `'quit'`, or None when handled here."
        src, line = self.buf.text, self.buf.text.strip()
        self.complete, self.desc = None, []
        self._echoed = []
        self.buf.clear()
        if not line: return None
        if line in ('/agent_proxy', '/agent-proxy'): return self.enable_agent_proxy()
        if line in ('/python', '/py'): return self.enter_python()
        if line in ('/agent', '/a'):
            self.mode = 'agent'
            return self.note('agent mode' if self.kernel is not None else 'agent mode; no kernel is running')
        if line in ('/vars', '/v'):
            try: return self.note(self.agent.host.list_vars() or '(nothing bound yet)')
            except Exception as e: return self.note(agent_err(e), 'error')
        if (parts := line.split())[0] in ('/promote', '/adopt'):
            if len(parts) != 2: return self.note('usage: /promote NAME')
            return self._promote(parts[1])
        if self.mode == 'python' and not line.startswith('/'):
            from ramabana.pyrepl import hl
            # raw buffer: an indented paste keeps its first row
            self._echo(hl(src), 'user', source=src)
            return self.run_code(src)
        if not line.startswith('/') and (opts := options_for(line)) is not None:
            self.menu_prompt, self.menu = line, ChoiceMenu(*opts)
            return None
        self._echo(Text(line), 'user', pad=True)
        if line in ('/quit', '/exit', '/q'): return 'quit'
        if line == '/kernels':
            from ramabana.pyrepl import sessions
            return self.note(sessions())
        if (bits := line.split())[0] == '/join':
            if len(bits) != 2:
                from ramabana.pyrepl import sessions
                self.note(sessions())
                return self.note('usage: /join NAME-or-URL')
            return self._join(bits[1])
        if line in ('/help', '/?'): self.say(key_card(HELP), 'note', fold=None, source=HELP); return None
        if line == '/guide':
            self.say(guide_text(g := self.guide()), 'note', fold=None, source=g)
            return None
        name, _, arg = line.partition(' ')
        arg = arg.strip()
        if name in ('/attach', '/add'):
            if not arg: return self.note('usage: /attach PATH [PATH ...]')
            found = media_paths(arg) or [media_path(arg)]
            return self.note('\n'.join(self.attach(p) for p in found))
        if name == '/detach': return self.note(self.detach(arg))
        if name == '/paste': return self.note(self.attach_clipboard())
        if name == '/copy': return self.note(self.copy_last(arg))
        if name == '/mouse': return self.note(self.set_mouse(arg))
        if name == '/approve': return self.note(self.approve_mode(arg))
        if name == '#note': return self.note(self.note_memory(arg))
        if line.startswith('/') and self.starting: return self.note(f'{name} waits for the model · try again once it is ready')
        if line.startswith('/'):
            out = self.agent.command(line)
            if out is None and (body := self.agent.expand_command(line)) is not None: return self._turn(body)
            kind = 'plan' if name in ('/plan', '/todo', '/todos') and out is not None else (
                'note' if out is not None else 'error')
            self.say(Text(out) if out is not None else Text(f'unknown command: {line}'),
                     kind, fold=None, source=out)
            if name in ('/plan', '/todo', '/todos'): self.show_plan = bool(self.agent.plan)
            return None
        if not self._hold and self.steer(line): return None
        got = [self.attach(p) for p in attach_refs(line)]
        if got: self.note('\n'.join(got))
        return self._turn(line)

    def on_key(self, k):
        "One keystroke. Returns a coroutine to spawn, `'quit'`, or None."
        self._key_at = time.monotonic()
        if self.mode == 'python' and self.ask is None and not self.buf.text.lstrip().startswith('/'):
            if (k.name == 'tab' and self.complete is None and self.turn is None
                    and self.buf.text): return self.complete_python()
            if k.name == 'shift+enter' and self.menu is None:
                self.buf.insert('\n')
                return self.paint()
            if (k.name == 'enter' and self.menu is None and self.buf.text.strip()
                    and not self.buf.text.endswith('\n\n')):
                from ramabana.pyrepl import _syntax_note, code_state
                state = code_state(self.buf.text)
                if state == 'incomplete':
                    self.buf.insert('\n')
                    return self.paint()
                if state == 'invalid':
                    self.say(Text(f'incomplete or invalid: {_syntax_note(self.buf.text)}'), 'error', fold=None)
                    return self.paint()
            if k.name == 'ctrl+c' and self.turn is not None:
                self.comp.spawn(self.kernel.interrupt(), name='interrupt')
                self.buf.clear()
                return self.paint()
        self.desc = []
        if self.menu is not None:
            done, choice = self.menu.choose(k.name)
            if not done: return self.paint()
            prompt, self.menu_prompt, self.menu = self.menu_prompt, '', None
            self._echoed = []
            if choice is None or choice.suffix is None:
                self.buf.text, self.buf.cursor = prompt, len(prompt)
                return self.paint()
            self._echo(Text(prompt), 'user')
            self._echo(Text(f'{choice.label} -- {choice.note}'), 'note')
            self.paint()
            return self._turn(prompt + choice.suffix)
        if self.complete is not None and k.name in ('tab', 'shift+tab', 'up', 'down'):
            if k.name in ('tab', 'down'): self.complete.cycle(1)
            else: self.complete.cycle(-1)
            return self.paint()
        if self.complete is not None and k.name == 'escape':
            self.complete = None
            return self.paint()
        if k.name == 'ctrl+t':
            self.show_plan = not self.show_plan
            return self.paint()
        if k.name == 'shift+tab':
            self.flash(self.cycle_approve())
            return self.paint()
        if self.ask is not None:
            bare = not self.buf.text.strip()
            if bare and k.name in ('y', 'Y'):     self.answer(True)
            elif bare and k.name == 'A' and self.always_allow(): pass
            elif bare and k.name in ('a', 'A'):   self.answer(True, session=True)
            elif k.name == 'enter':
                if (ans := parse_answer(self.buf.text)) is None: self.buf.clear(); self.reask(NOT_ANSWER)
                else: self.answer(ans[0], note=ans[1])
            elif k.name == 'ctrl+y':              self.answer(True)
            elif k.name == 'ctrl+c':              self.answer(False)
            else: self.buf.handle(k)
            return self.paint()
        if k.name == 'ctrl+d' and not self.buf.text: return 'quit'
        if k.name == 'ctrl+c':
            self.buf.clear()
            if self.turn is not None: return self.stop()
            return self.paint()
        if k.name in ('enter', 'shift+enter', 'alt+enter'):
            self._hold = k.name != 'enter'
            coro = self.submit()
            self._hold = False
            self.paint()
            return coro
        if k.name == 'ctrl+v':
            self.note(self.attach_clipboard())
            return self.paint()
        if k.name == 'ctrl+g':
            self.note(self.tighten_approve())
            return self.paint()
        if k.name == 'ctrl+o':
            self.fold_work()
            return self.paint()
        if k.name.startswith('alt+') and k.name[4:].isdigit() and k.name[4:] != '0':
            self.drill(int(k.name[4:]))
            return self.paint()
        if k.name == 'tab' and self.buf.text.startswith('/') and self.complete is None:
            self._refresh_complete()
            if self.complete is not None:
                if not self.complete.insert_common(): self.complete.cycle(1)
                return self.paint()
        self.buf.handle(k)
        if self.buf.text.startswith('/'): self._refresh_complete()
        else:
            self.complete, self.desc = None, []
            self._suggest_soon()
        self.paint()

    def reply(self, text):
        "How a model reply renders. Plain here; the Markdown layer below patches it."
        return Text(text)

    def flush_stream(self):
        "Render the open segment now, ignoring `STREAM_EVERY`."
        if self._seg_blk is None or not self._seg or self._seg == self._rendered: return
        self.comp.set_body(self._seg_blk, self.reply(self._seg), source=self._seg)
        self.comp.refresh_block(self._seg_blk)
        self._rendered, self._painted_at = self._seg, time.monotonic()
        self.touch()

    def stream(self, blk, chunk):
        "Grow the current segment, opening a block after a call ended the last."
        if blk is None: self._seg_blk = None
        if self._seg_blk is None: self._seg = ''
        self._seg += chunk
        self._reply += chunk
        if self._seg_blk is None:
            self._seg_blk = self.say(self.reply(self._seg), 'reply', fold=None, source=self._seg)
            self._rendered, self._painted_at = self._seg, time.monotonic()
        else:
            self._seg_blk.source = self._seg
            if time.monotonic() - self._painted_at >= STREAM_EVERY: self.flush_stream()
        return self._seg_blk

