@patch
def model_row(self:Ui):
    "The row under the bar: the next turn's model, from the routing table."
    try: note = model_note(self.agent.model)
    except Exception as e: note = agent_err(e)
    if (p := getattr(self.agent, 'profile', '')): note += f' · {p} profile'
    row = Text(' ')
    if (c := self.chip()) is not None: row.append_text(c).append('  ')
    return row.append(note, style=GRUVBOX['gray'])

@patch
def tail(self:Ui):
    "The live-tail description shared with Teleprint's transcript view."
    rows = [self.status(), self.model_row()]
    if self.hint: rows.append(Text(' ' + self.hint, style=GRUVBOX['gray']))
    chips = self.attach_row()
    if chips is not None: rows.append(chips)
    rows += self.working()
    for r in (self.queued_row(), self.flash_row()):
        if r is not None: rows.append(r)
    rows.append(self.prompt())
    before = Text(self._prefixed(self.buf.text[:self.buf.cursor]))
    rendered = self.comp.console.render_lines(before, pad=False)
    cursor = (len(rows) - 1, len(rendered) - 1, sum(s.cell_length for s in rendered[-1]))
    return rows, cursor

@patch
def recall(self:Ui, step):
    "Move through submitted prompts, preserving the draft beyond the newest entry."
    if not self.history: return False
    if self.history_at == len(self.history): self.draft = self.buf.text
    self.history_at = max(0, min(len(self.history), self.history_at + step))
    text = self.draft if self.history_at == len(self.history) else self.history[self.history_at]
    self.buf.text, self.buf.cursor = text, len(text)
    return True

_core_submit = Ui.submit

@patch
def remember(self:Ui, line):
    "Keep `line` for Ctrl-P/Ctrl-N recall."
    if line and (not self.history or self.history[-1] != line): self.history.append(line)
    self.history_at, self.draft = len(self.history), ''

@patch
def submit(self:Ui):
    "Submit the line and remember it for Ctrl-P/Ctrl-N recall."
    self.remember(self.buf.text.strip())
    return _core_submit(self)

_core_on_key = Ui.on_key

@patch
def enter_transcript(self:Ui):
    "Open the browsing view, borrowing the mouse while it is up."
    self.flush_stream()   # flush first: the view renders block bodies
    self.comp.tty.write(MOUSE_ON)
    self.transcript.enter()

@patch
def leave_transcript(self:Ui):
    "Close the browsing view and return the mouse unless `/mouse` is on."
    self.transcript.leave()
    if not self.mouse: self.comp.tty.write(MOUSE_OFF)

@patch
def set_mouse(self:Ui, want=''):
    "Take or release the mouse on the main screen; off by default."
    want = (want or '').strip().lower()
    if want not in ('', 'on', 'off', 'toggle', 'yes', 'no'): return 'usage: /mouse [on|off]'
    self.mouse = not self.mouse if want in ('', 'toggle') else want in ('on', 'yes')
    if not self.transcript.active: self.comp.tty.write(MOUSE_ON if self.mouse else MOUSE_OFF)
    return ('mouse on: click a block to fold it, wheel up to browse; shift-drag still selects'
            if self.mouse else 'mouse off: selection belongs to the terminal again')

@patch
def on_mouse(self:Ui, ev):
    "Route a mouse event to the browsing view, or here when `/mouse` is on."
    if self.transcript.active: return self.transcript.on_mouse(ev)
    if not self.mouse: return True
    if ev.press and ev.btn == 64:
        self.enter_transcript()
        return True
    return ev.press and ev.btn == 65

@patch
def on_key(self:Ui, k):
    "Give transcript navigation priority; Ctrl-P/Ctrl-N recall prompts."
    view = self.transcript
    if view.active:
        if view.on_key(k): return None
        if k.name == 'escape':
            self.leave_transcript()
            return self.paint()
        if k.name == 'enter':
            if not view.composing: return None
            out = self.submit()
            self.leave_transcript()
            self.paint()
            return out
        out = _core_on_key(self, k)
        view.rebuild(bottom=view.follow)
        return out
    if (k.name == 'ctrl+r' or (k.name in ('up', 'down') and not self.buf.text)) and self.ask is None:
        self.enter_transcript()
        if k.name in ('up', 'down'): view.on_key(k)
        return None
    if k.name in ('ctrl+p', 'ctrl+n'):
        self.recall(-1 if k.name == 'ctrl+p' else 1)
        return self.paint()
    return _core_on_key(self, k)

@patch
def paste(self:Ui, text):
    "Insert pasted text, or attach the files when the paste is nothing but paths."
    found = media_paths(text)
    if found:
        for p in found: self.attach(p)
    else: self.buf.insert(text)
    if self.transcript.active:
        if not found: self.transcript.composing = True
        return self.transcript.rebuild(bottom=self.transcript.follow)
    return self.paint()

DIFF_LEXERS = {'diff', 'patch', 'udiff'}

@functools.cache
def _hl_langs(): return frozenset(fastpylight.languages()) - {'plaintext'}

def fence_lang(name):
    "fastpylight's name for a fence's language: 'diff' for a patch, None when it has no grammar."
    name = (name or '').lower()
    if name in DIFF_LEXERS: return 'diff'
    if name in _hl_langs(): return name
    return None if (g := fastpylight.guess('', f'x.{name}')) == 'plaintext' else g

class ThemedCode(CodeBlock):
    "A fenced block on the palette's background: a diff by `diff_rich`, known code by fastpylight, else pygments."
    def __rich_console__(self, console, options):
        code, lang = str(self.text).rstrip(), fence_lang(self.lexer_name)
        try: t = None if lang is None else diff_rich(code) if lang == 'diff' else hl_text(code, lang)
        except Exception: t = None
        if t is None: yield Syntax(code, self.lexer_name, theme=code_theme(), background_color=code_bg(), word_wrap=True, padding=(0, 1))
        else: yield Padding(t, (0, 1), style=f'on {code_bg()}', expand=True)

class Reply(Markdown):
    "Rich's `Markdown` with our code block."
    elements = {**Markdown.elements, 'code_block': ThemedCode, 'fence': ThemedCode}

BLOCK_START = re.compile(r'( {4,}|\t|\s*(#{1,6}\s|>|[-*+]\s|\d+[.)]\s|\||```|~~~|-{3,}$|={3,}$))')

def _prose(line): return bool(line.strip()) and not BLOCK_START.match(line)

def compact_md(text):
    "Markdown with blank rows between plain paragraphs made hard breaks."
    lines, out, fence, prose_block = str(text).split('\n'), [], '', False
    for i, line in enumerate(lines):
        mark = line.strip()[:3]
        if mark in ('```', '~~~'):
            fence = '' if fence == mark else (fence or mark)
            prose_block = False; out.append(line); continue
        if fence: out.append(line); continue
        if line.strip():
            if not out or not out[-1].strip(): prose_block = _prose(line)
            out.append(line); continue
        nxt = next((l for l in lines[i + 1:] if l.strip()), '')
        if prose_block and out and out[-1].strip() and _prose(nxt):
            if not out[-1].endswith('  '): out[-1] += '  '
            continue
        out.append(line)
    return '\n'.join(out)

@patch
def reply(self:Ui, text):
    "A model reply as Markdown in this palette, prose compacted."
    return Reply(compact_md(text), code_theme=code_theme(), style=GRUVBOX['fg1'])

