async def amain(agent, hint='', python=False, attach='', agent_proxy=False, bell=True, pane='auto'):
    "The tty loop: one terminal, one event loop, one keyboard owner."
    tty = RealTty()
    tty.write('\x1b[?2004h')
    done = asyncio.Event()
    ui = None
    try:
        comp = await Compositor(tty).start()
        ui = Ui(comp, agent, loop=asyncio.get_running_loop())
        ui.bell = bell
        ui.hint = hint
        comp.on_task_error = lambda e, t: ui.say(Text(f'{t.get_name()} failed: {e!r}'), 'error')
        comp.spawn(ui.animate(), name='spinner')
        def on_key(k):
            out = ui.on_key(k)
            if out == 'quit': return done.set()
            if out is not None:
                ui.start_turn(out)
                ui.paint()
        comp.on_key = on_key
        comp.on_paste = ui.paste
        comp.on_resize = lambda: (comp.resize(), ui.paint())
        comp.on_mouse = ui.on_mouse
        if agent.plan:
            ui.say(plan_text(agent.plan.md()), 'plan', fold=None, source=agent.plan.md())
            ui.show_plan = True
        else: ui.say(Text('tab completes /commands · ctrl+t toggles the plan · /help for keys', style=GRUVBOX['gray']), 'note', fold=None)
        if attach or python or agent_proxy: await ui.warm_up()   # the kernel's host replaces this one, on a started model
        else: ui.begin()
        if attach: ui.hint = f'{hint} · attached to {await ui.attach_session(attach)}'
        elif python or agent_proxy:
            await ui.enter_python()
            if agent_proxy: await ui.enable_agent_proxy()
        ui.start_pane(pane)
        ui.paint()
        loop = asyncio.get_running_loop()
        loop.add_reader(tty.fd, lambda: comp.on_bytes(tty.read(timeout=0)))
        try:
            while not done.is_set():
                try: await asyncio.wait_for(done.wait(), 0.2)
                except asyncio.TimeoutError: comp.flush_input()
        finally:
            loop.remove_reader(tty.fd)
            comp.stop()
    finally:
        if ui is not None: ui.close_pane()
        tty.write('\x1b[?2004l' + MOUSE_OFF + (KEYS_OFF if ext_keys_ok(tty) else '') + '\r\n')   # `stop` never ran if setup raised
        tty.restore()
        if ui is not None: ui.closed = True
        agent.close()
        if ui is not None and ui.agent_bridge is not None: await ui.agent_bridge.close()
        if ui is not None and ui.kernel is not None: await ui.kernel.shutdown()

