def host_kw(tmux='auto'):
    "The CLI's host options: `--tmux`, and no code index until the model is up."
    return dict(tmux=TMUX_MODES[tmux], index=False)

@call_parse(pos=['prompt'])
def main(
    prompt: str = '',                    # one turn and exit; omit for interactive
    root: str = '.',                     # comma-separated folders: .,~/notes,/srv/app
    model: str = None,                   # turn model; omit for the routing default
    approve: str = 'ask',                # ask | edits | auto | off | none (no gate)
    web: bool = True,                    # --no-web takes the web tools offline
    read_outside: bool = False,          # reads reach any path; writes need --root
    subagent_writes: bool = False,       # let sub-agents write, run commands and Python
    vault: bool = False,                 # vishalakshi vault for reads; not in python mode
    pii: str = PII_OFF,                  # off | redact | refuse PII from the vault
    pii_ner: bool = False,               # --pii also gates titled names
    spec: bool = False,                  # enable OpenAPI, Azure and Google Discovery tools
    theme: str = 'auto',                 # auto | dark | light terminal palette
    max_tool_calls: str = 'auto',        # auto | 20..400 tool calls per turn
    max_steps: str = 'auto',             # auto | 8..80 model/tool-loop steps per turn
    cfg: str = '~/.config/ramabana',     # config dir: skills, extensions, resumable history
    resume: str = '',                    # saved session id/prefix, or 'latest'
    python: bool = False,                # start in python mode, on a kernel of your own
    attach: str = '',                    # join a live session; --kernels lists them
    agent_proxy: bool = False,           # expose a restricted agent proxy in PyREPL
    kernels: bool = False,               # list live sessions and exit
    json: bool = False,                  # with a prompt: print the full result as JSON
    bell: bool = True,                   # --no-bell silences turn-end and approval bells
    tmux: str = 'auto',                  # auto | on | off: read and run in tmux panes
    pane: str = 'auto',                  # auto | on | off: the `now` pane; auto in tmux
    doctor: bool = False,                # check tmux and the now pane, offer to install tmux, and exit
    warm: bool = False,                  # seed example rounds even in the small profile
    no_warm: bool = False,               # start without dhrona's example rounds
    optin: str = '',                     # opt-in tool groups: exhash,research,author
    profile: str = 'auto',               # auto | small | full: small suits ≤32k local models
):
    "Run Ramabana as a terminal agent or Python prompt. Name every folder it may work on: --root .,~/notes"
    if doctor: return Setup(cfg).doctor()
    if (kernels or python or attach or agent_proxy) and (msg := need('python')):
        print(msg, file=sys.stderr)
        return 2
    if kernels:
        from ramabana.pyrepl import sessions
        print(sessions())
        return 0
    if (msg := refusal(tmux, pane, profile, pii, vault, python, attach, agent_proxy, warm, no_warm)):
        print(msg, file=sys.stderr)
        return 2
    prompt = headless_prompt(prompt)
    if prompt and approve == 'ask':
        print('one-shot runs have nobody to ask, so every write will be refused · pass --approve auto', file=sys.stderr)
    if attach:
        from ramabana.pyrepl import find_session
        try: attach = find_session(attach)
        except RuntimeError as e:
            print(e, file=sys.stderr)
            return 2
    if not setup.LAUNCHED: Setup(cfg).launch(prompt, json, tmux)
    roots = [r.strip() for r in str(root).split(',') if r.strip()]
    try: set_theme(theme)
    except ValueError as e:
        print(e, file=sys.stderr)
        return 2
    try: agent, host = mk_agent(roots, model=model, approve=approve, web=web, vault=vault, spec=spec,
                               read_outside=read_outside, subagent_writes=subagent_writes,
                               pii=pii, pii_ner=pii_ner, host_kw=host_kw(tmux),
                               max_tool_calls=max_tool_calls, max_steps=max_steps,
                               warm=True if warm else False if no_warm else None, optin=tuple(s.strip() for s in optin.split(',') if s.strip()), profile=profile,
                               cfg=Path(cfg).expanduser() if cfg else None)
    except KeyError as e:
        print(e.args[0] if e.args else e, file=sys.stderr)
        return 2
    except (RuntimeError, AgentError) as e:
        print(e, file=sys.stderr)
        return 2
    if resume:
        try: agent.resume_session(resume)
        except Exception as e:
            print(f'could not resume: {agent_err(e)}', file=sys.stderr)
            return 2
        if (was := getattr(agent, 'resumed_roots', None)):
            print(f'that session had also opened {", ".join(was)} · /root add PATH to open again', file=sys.stderr)
    if prompt:
        start_agent(agent)
        return sys.exit(ask_once(agent, prompt, as_json=json))
    hint = f"{', '.join(host.roots)} · /python · /help"
    try: asyncio.run(amain(agent, hint, python=python, attach=attach, agent_proxy=agent_proxy, bell=bell, pane=pane))
    except KeyboardInterrupt: pass

