def pane_cmd(path):
    "The shell line that draws the `now` pane for `path`."
    exe = shutil.which('ramabana-pane')
    return shlex.join([exe, str(path)] if exe else [sys.executable, '-m', 'ramabana.pane', str(path)])

def _tmux_pane(host):
    "The tmux pane `host` runs in, or None outside tmux or with `--tmux off`."
    try: return getattr(host, 'tmux_pane', None)
    except Exception: return None

def _alive(pane):
    "Whether `pane` still draws, not ended or kept dead by `remain-on-exit`."
    try: return not pane.refresh().dead
    except Exception: return False

ALIVE_EVERY = 1.0    #: seconds between asks whether the viewer still draws
REOPEN_EVERY = 10.0  #: seconds between reopenings of a viewer that died
QUICK_DEATH = 5.0    #: a viewer that dies younger than this died at once
REVIVE_TRIES = 3     #: quick deaths in a row before the pane is given up

_act_now = Ui._act
@patch
def _act(self:Ui, act):
    out = _act_now(self, act)
    self.write_now()
    return out

@patch
def open_pane(self:Ui, arg=''):
    "`/pane` opens the `now` pane in a tmux split on the right; `/pane off` closes it."
    if arg == 'off': return self.note(self.close_pane() or 'no pane is open')
    if arg: return self.note('usage: /pane [off]', 'error')
    if (p := _now_file(self.agent)) is None: return self.note('the pane reads <cfg>/runs, and this session has no --cfg', 'error')
    if self.pane is not None and self._pane_at == p and _alive(self.pane):
        return self.note(f'the pane is already open in {self.pane.id} · /pane off closes it')
    self.close_pane()
    quit_mark(p).unlink(missing_ok=True)
    self.write_now(force=True)
    cmd = pane_cmd(p)
    if (me := _tmux_pane(self.agent.host)) is None:
        why = 'tmux is turned off (--tmux off)' if getattr(self.agent.host, '_tmux', None) is False else 'no tmux here'
        return self.note(f'{why}; in another terminal run: {cmd}')
    try: self.pane, self._pane_at, self._opened_at = me.split('right', cmd, size='35%'), p, time.monotonic()
    except Exception as e: return self.note(f'the pane did not open ({agent_err(e)}); in another terminal run: {cmd}', 'error')
    return self.note(f'the pane is open in {self.pane.id} · /pane off closes it')

@patch
def close_pane(self:Ui):
    "Kill the `now` pane: what was closed, or '' when none was open."
    if (p := self.pane) is None: return ''
    self.pane, alive = None, _alive(p)
    try: p.kill()
    except Exception: pass
    return f'closed the pane {p.id}' if alive else f'the pane {p.id} was already closed'

@patch
def _revive(self:Ui):
    "Reopen the `now` pane when its viewer crashed, not quit: asked at most every `ALIVE_EVERY`, reopened at most every `REOPEN_EVERY`, given up after `REVIVE_TRIES` quick deaths."
    t = time.monotonic()
    if self.pane is None or t - self._alive_at < ALIVE_EVERY: return
    self._alive_at = t
    if _alive(self.pane): return
    if quit_mark(self._pane_at).exists(): return self.close_pane()
    if self._opened_at is not None:
        self._quick, self._opened_at = self._quick + 1 if t - self._opened_at < QUICK_DEATH else 0, None
        if self._quick >= REVIVE_TRIES:
            self.close_pane()
            return self.note('the pane keeps exiting; run `ramabana --doctor`', 'error')
    if t - self._reopen_at < REOPEN_EVERY: return
    self._reopen_at = t
    self.open_pane()

@patch
def start_pane(self:Ui, mode='auto'):
    "Open the first pane: `on` always tries, `auto` only in tmux with a runs dir."
    if mode == 'on' or (mode == 'auto' and _now_file(self.agent) and _tmux_pane(self.agent.host)): self.open_pane()
